    pool: TAccountMetas[3];
    mint: TAccountMetas[4];
    usdcMint: TAccountMetas[5];
    adminUsdcAccount: TAccountMetas[6];
    usdcVault: TAccountMetas[7];
    poolCpVault: TAccountMetas[8];
